// QueueAPM.cpp : Defines the entry point for the DLL application.#include "stdafx.h"#include "MnemoWnd.h"#include "QueueWnd.h"#include "Lang.h"#include "Function.h"#include <math.h>//void OutputQueue(HDC hDC,SQueue& q,SBuffer& Buffer,SUniLogic* u);int PaintNull(DefinePaint)  {  return SkipQueue(szQueue);  }int PaintLibrary(DefinePaint)  {  Queue_Library* p = (Queue_Library*)szQueue;  if ( p->paint )    {    (*p->paint)( hDC, szQueue, q, beginQ, u );    }  else    {    QueueP( Queue_Library );    }  //  //CMyPen   pn( hDC, 0x80ff, 0 );  //pn.Rect( p->rc );  //  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Отрисовка очереди макросаint PaintMacros(DefinePaint)  {  QueueP(Queue_Macros);  if ( p->nParams < 0 ) return 1;  OutputQueue( hDC, q, p->Buffer, u );  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~static  LPFuncPaint gs_funcPaint[TYPE_UNKNOWN+1];static void Init(SQueue& q)  {  for ( int n = 0; n < TYPE_UNKNOWN+1; n++ )    gs_funcPaint[n] = PaintNull;  //  gs_funcPaint[TYPE_MACROS ] = PaintMacros;  gs_funcPaint[TYPE_LIBRARY] = PaintLibrary;  }////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void OutputQueue(HDC hDC,SQueue& q,SBuffer& Buffer,SUniLogic* u)  {  LPBYTE szQueue = Buffer.szQueue;  if ( szQueue )    {    int nMode = ::SetBkMode(hDC,TRANSPARENT);    int n = 0;    while ( gs_funcPaint[*szQueue](hDC,szQueue,q,Buffer.szQueue,u) ) n++;    ::SetBkMode(hDC,nMode);    }  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void OutPribor(HDC hDC,SQueue& q,bool bStat,CQueueWnd* pWnd)  {  if ( q.cntPribor <= 0 ) return;  //	Graphics gr( hDC );  if ( bStat )    {    for ( int n = 0; n < q.cntPribor; n++ )    PaintStatic ( q.arrPribor[n], gr );    }  else    {    bool bRect = ::IsMnemoStyle(MNEMO_PRIBOR);    if ( !bRect )      bRect = pWnd->m_bRegionView;    for ( int n = 0; n < q.cntPribor; n++ )    PaintDynamic( q.arrPribor[n], gr, bRect );    }  //  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Вывод буквы режимаvoid PaintRegimChar( HDC hDC, int x, int y, int n )  {  char szS[8] = "\0";  sprintf_s( szS, sizeof(szS), "%c", 0x8b + abs(n) );  LOGFONT lf;  memset(&lf,0,sizeof(lf));  lf.lfCharSet = DEFAULT_CHARSET;  lf.lfHeight  = -30;  lstrcpy(lf.lfFaceName,"Wingdings");  //  HFONT hFont = ::CreateFontIndirect( &lf );  if ( hFont )    {    HFONT hOldF = (HFONT)::SelectObject( hDC, hFont );    COLORREF ss = ::SetTextColor(hDC,0xFF0000);    int nMode = ::SetBkMode( hDC, TRANSPARENT );    ::TextOut( hDC, x, 0, szS, lstrlen(szS) );    ::SetBkMode( hDC, nMode );    ::SetTextColor(hDC,ss);    ::SelectObject( hDC, hOldF );    ::DeleteObject( hFont );    }  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Вывод информации для Сергеяvoid PaintSergej(HDC hDC,SQueue& q)  {  // Работает только с флагом 0x40  if ( ::IsMnemoStyle(MNEMO_HIDE_SCN) == 0 ) return;  //  POINT point;  PtWt( point, q );  if ( point.x > 0 || point.y > 0 )    {    char sz[64];    sprintf_s(sz,64,"(%d-%d)",point.x,point.y);    ::TextOut( hDC, 200, 5, sz, lstrlen(sz) );    }  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void PaintQueue(HDC hDC,SQueue& q,CQueueWnd* pWnd)  {  INIT  if ( q.hWnd == NULL )    return;  //  RECT clientRect;  ::GetClientRect( q.hWnd, &clientRect );  //  int clientWidth  = clientRect.right-clientRect.left;  int clientHeight = clientRect.bottom-clientRect.top;  int nWidth  = clientWidth;  int nHeight = clientHeight;		  if (pWnd->ExistsVScrollBar())	  nHeight  = q.szWnd.cy;  if (pWnd->ExistsHScrollBar())	  nWidth  = q.szWnd.cx;  //  bool bPaintStat = false;  if ( pWnd->Code() == 0 && q.szWnd.cx > 0 && q.szWnd.cy > 0 )    {    FLOAT x  = FLOAT( nWidth  )/ q.szWnd.cx;    FLOAT y  = FLOAT( nHeight )/ q.szWnd.cy;    if ( ::IsMnemoStyle(MNEMO_ONLY) )      q.setScale = 1;    else      q.setScale = min( x, y );    }  int vScrollShift = pWnd->GetVscrollPosition();  int hScrollShift = pWnd->GetHscrollPosition();  //  if ( GiveBitmap( hDC, nWidth, nHeight, q.bmpStat) ) bPaintStat = true;  if ( q.bmpFull != NULL )    {    ::DeleteObject(q.bmpFull);    q.bmpFull = NULL;    }  GiveBitmap( hDC, nWidth, nHeight, q.bmpFull);  //  if ( q.bmpStat == NULL || q.bmpFull == NULL )    return;  //  if ( !bPaintStat )    bPaintStat = (q.setShift.x != q.curShift.x || q.setShift.y != q.curShift.y);  if ( !bPaintStat )    bPaintStat = (q.setScale != q.curScale);  if ( !bPaintStat )    bPaintStat = (nWidth != q.curWidth) || (nHeight != q.curHeight) ;  //  q.curShift  = q.setShift;  q.curScale  = q.setScale;  q.curWidth  = nWidth ;  q.curHeight = nHeight;  //  HDC hdc = ::CreateCompatibleDC( hDC );  if ( hdc != NULL )    {    static LARGE_INTEGER fr,c0,c1,c2,c3,c4,c5,c6,c7,c8,c9;    QueryPerformanceFrequency(&fr);    QueryPerformanceCounter(&c8);    //    HBITMAP oldBmp = (HBITMAP)::SelectObject( hdc, q.bmpFull );    HDC idc = ::CreateCompatibleDC( hdc );    if ( idc != NULL )      {      HBITMAP ildBmp = (HBITMAP)::SelectObject( idc, q.bmpStat );      if ( bPaintStat )        {        QueryPerformanceCounter(&c0);        CMyWT wt( idc, q );        OutputQueue( idc, q, q.Stat, NULL );        OutPribor  ( idc, q, true, pWnd );        QueryPerformanceCounter(&c1);        }      //      // Копируем битмап со статическими элементами в полный битмап      QueryPerformanceCounter(&c2);      ::BitBlt( hdc, 0, 0, nWidth, nHeight, idc, 0, 0, SRCCOPY );      QueryPerformanceCounter(&c3);      ::SelectObject( idc, ildBmp );      ::DeleteDC(idc);      }    {//////////////////////////////////////////////////////    QueryPerformanceCounter(&c4);    CMyWT wt( hdc, q );    pWnd->mLogic.Begin();    OutputQueue( hdc, q, q.Dyna, &pWnd->mLogic );    OutPribor  ( hdc, q, false, pWnd );    QueryPerformanceCounter(&c5);    //    // Вывод режима отображения    if ( pWnd->Code() == 0 )      PaintSergej( hdc, q );    if ( pWnd->m_nMorg > 0 )      {      if ( pWnd->m_nMorg % 2 )      ::InvertRect( hdc, &pWnd->m_rcMorg );      pWnd->m_nMorg--;      }    }//////////////////////////////////////////////////////    //    //    // Копируем битмап со всеми элементами на экран    QueryPerformanceCounter(&c6);    ::BitBlt( hDC, 0, 0, nWidth, nHeight, hdc, hScrollShift, vScrollShift, SRCCOPY );    QueryPerformanceCounter(&c7);    ::SelectObject( hdc, oldBmp );    ::DeleteDC(hdc);    QueryPerformanceCounter(&c9);    //#if 1    if ( ::IsMnemoStyle(MNEMO_TIME) )      {      int dd = ::GetDeviceCaps( hDC, RASTERCAPS );      BITMAP info;      ::GetObject( q.bmpFull, sizeof(BITMAP), &info);      char sz[128];      double t0 = ((c1.LowPart-c0.LowPart)*1000.)/fr.LowPart;      double t1 = ((c3.LowPart-c2.LowPart)*1000.)/fr.LowPart;      double t2 = ((c5.LowPart-c4.LowPart)*1000.)/fr.LowPart;      double t3 = ((c7.LowPart-c6.LowPart)*1000.)/fr.LowPart;      double t4 = ((c9.LowPart-c8.LowPart)*1000.)/fr.LowPart;      sprintf_s(sz,127,"(Qs %.4f)(Qb %.4f) (Qd%.4f)(Qb%.4f) %.4f",t0,t1,t2,t3,t4);      ::TextOut( hDC, 150, 20, sz, lstrlen(sz) );      }#endif    }}